<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, shallowRef } from "vue"
import { useRouter } from "vue-router"
import { errorMessage, loadSharedModel, unloadModel } from "@/modelLifecycle"
import { captureVideoFrame, wait, waitForNextVideoFrame } from "@/object_detection/frame"
import { estimatePoses, fetchHandResourceStatus } from "@/pose_estimation/api"
import type { ResourceStatus, VisionOptions } from "@/vision/types"
import { ThunderAudio } from "./audio"
import { DIFFICULTIES, HAND_MODEL_ID } from "./config"
import { PalmThunderEngine } from "./engine"
import { HandTracker } from "./gestures"
import { ThunderRenderer } from "./renderer"
import type { Difficulty, GamePhase, GameSnapshot, Point, TrackedHand, WeaponMode } from "./types"

const phase = ref<GamePhase>("lobby"), difficulty = ref<Difficulty>("arcade"), resource = ref<ResourceStatus | null>(null)
const router = useRouter()
const playerCount = ref<1 | 2>(1)
const modelInstanceId = ref<string | null>(null), modelBusy = ref(false), cameraReady = ref(false), error = ref(""), countdown = ref<string | number>(3)
const video = ref<HTMLVideoElement | null>(null), stage = ref<HTMLElement | null>(null), canvas = ref<HTMLCanvasElement | null>(null), stream = ref<MediaStream | null>(null)
const snapshot = shallowRef<GameSnapshot | null>(null), hands = shallowRef<TrackedHand[]>([]), inferenceMs = ref<number | null>(null), soundEnabled = ref(true)
const pointerPosition = shallowRef<Point | null>(null)
const mouseStartRequested = ref(false)
const captureCanvas = document.createElement("canvas"), tracker = new HandTracker(), audio = new ThunderAudio()
let engine: PalmThunderEngine | null = null, renderer: ThunderRenderer | null = null, frameId = 0, generation = 0, lastAt = 0, aborter: AbortController | null = null, observer: ResizeObserver | null = null

const modelAvailable = computed(() => resource.value?.artifacts.some((a) => a.available && ["coreml", "onnx"].includes(a.runtime ?? "")) ?? false)
const joinedPlayers = computed(() => snapshot.value?.players.filter((p) => p.joined) ?? [])
const statusText = computed(() => hands.value.some((h) => h.active) ? `${hands.value.filter((h) => h.active).length} HAND${hands.value.filter((h) => h.active).length > 1 ? "S" : ""} LOCKED` : pointerPosition.value ? "MOUSE CONTROL · LEFT CLICK TO BOMB" : "SHOW YOUR PALM OR MOVE THE MOUSE")
const modelStatus = computed(() => modelBusy.value ? "LOADING" : modelInstanceId.value ? "READY" : modelAvailable.value ? "AVAILABLE" : "MISSING")
const weaponLabel = (mode: WeaponMode): string => ({ vulcan: "VULCAN", spread: "SPREAD", laser: "LASER" })[mode]

async function loadResource(): Promise<void> { try { resource.value = await fetchHandResourceStatus() } catch (e) { error.value = errorMessage(e, "Could not read the hand model status") } }
async function ensureModel(): Promise<boolean> { if (modelInstanceId.value) return true; if (!modelAvailable.value) { error.value = "The hand detection model is not ready. Download and convert it on the Models page first."; return false } modelBusy.value = true; try { const runtime = resource.value!.artifacts.some((a) => a.runtime === "coreml" && a.available) ? "coreml" : "onnx"; modelInstanceId.value = (await loadSharedModel(HAND_MODEL_ID, "float", runtime)).instance_id; return true } catch (e) { error.value = errorMessage(e, "Model loading failed"); return false } finally { modelBusy.value = false } }
async function toggleModel(): Promise<void> { if (modelInstanceId.value) { await unloadModel(modelInstanceId.value); modelInstanceId.value = null } else await ensureModel() }
async function openCamera(): Promise<boolean> { try { stream.value = await navigator.mediaDevices.getUserMedia({ audio: false, video: { facingMode: "user", width: { ideal: 1280 }, height: { ideal: 720 }, frameRate: { ideal: 30 } } }); await nextTick(); if (!video.value) throw new Error("The game stage is not ready"); video.value.srcObject = stream.value; await video.value.play(); cameraReady.value = true; return true } catch (e) { error.value = e instanceof DOMException && e.name === "NotAllowedError" ? "Camera permission was denied" : errorMessage(e, "Could not start the camera"); closeCamera(); return false } }

async function start(): Promise<void> { error.value = ""; mouseStartRequested.value = false; pointerPosition.value = null; await audio.unlock(); if (!await ensureModel()) return; phase.value = "calibrating"; await nextTick(); if (!await openCamera()) { phase.value = "lobby"; return } setup(); tracker.reset(playerCount.value); hands.value = []; const token = ++generation; lastAt = performance.now(); frameId = requestAnimationFrame((now) => renderLoop(now, token)); void inferLoop(token); const deadline = performance.now() + 12_000; while (token === generation && hands.value.filter((h) => h.active).length < playerCount.value && !(playerCount.value === 1 && mouseStartRequested.value) && performance.now() < deadline) await wait(80); if (token !== generation) return; const handCount = hands.value.filter((h) => h.active).length; if (handCount < playerCount.value && !(playerCount.value === 1 && mouseStartRequested.value)) { error.value = playerCount.value === 2 ? "Two-player mode requires two complete hands in frame at the same time." : "No hand detected. Open your palm or click the stage to play with your mouse."; exit(); return } tracker.lock(); phase.value = "countdown"; engine!.setPhase("countdown"); for (const value of [3, 2, 1]) { countdown.value = value; audio.play("tick"); await wait(700); if (token !== generation) return } countdown.value = "FIGHT"; audio.play("go"); await wait(500); if (token !== generation) return; phase.value = "playing"; engine!.setPhase("playing") }
function setup(): void { if (!stage.value || !canvas.value) return; const rect = stage.value.getBoundingClientRect(); engine = new PalmThunderEngine(rect.width, rect.height, difficulty.value); engine.configurePlayers(playerCount.value); renderer = new ThunderRenderer(canvas.value); renderer.resize(rect.width, rect.height); observer = new ResizeObserver(() => { if (!stage.value || !engine || !renderer) return; const r = stage.value.getBoundingClientRect(); engine.resize(r.width, r.height); renderer.resize(r.width, r.height) }); observer.observe(stage.value) }
function renderLoop(now: number, token: number): void { if (token !== generation || !engine || !renderer) return; engine.setHands(hands.value); engine.setPointer(pointerPosition.value); if (phase.value === "playing") { for (const hand of hands.value) { if (tracker.consume(hand.id, "fist")) engine.triggerBomb(hand.id); if (tracker.consume(hand.id, "love")) engine.triggerLove(hand.id) } engine.update(now - lastAt) } lastAt = now; while (engine.events.length) audio.play(engine.events.shift()!); renderer.render(engine.state, hands.value); snapshot.value = { ...engine.state, players: engine.state.players.map((p) => ({ ...p })) }; if (engine.state.phase === "won" || engine.state.phase === "lost") phase.value = engine.state.phase; frameId = requestAnimationFrame((n) => renderLoop(n, token)) }
function updatePointer(event: PointerEvent): void { if (!stage.value) return; const rect = stage.value.getBoundingClientRect(); pointerPosition.value = { x: (event.clientX - rect.left) / rect.width, y: (event.clientY - rect.top) / rect.height } }
function handlePointerMove(event: PointerEvent): void { updatePointer(event) }
function handlePointerDown(event: PointerEvent): void { if (event.button !== 0) return; const target = event.target instanceof Element ? event.target : null; if (target?.closest("button,a")) return; updatePointer(event); if (phase.value === "calibrating" && playerCount.value === 1) { mouseStartRequested.value = true; return } const handControlsP1 = hands.value.some((hand) => hand.id === 1 && hand.active); if (phase.value === "playing" && !handControlsP1) engine?.triggerBomb(1) }
async function inferLoop(token: number): Promise<void> { let mediaTime = -1; while (token === generation && video.value && phase.value !== "lobby") { if (phase.value === "paused") { await wait(80); continue } try { if (video.value.currentTime <= mediaTime + .001) await waitForNextVideoFrame(video.value); mediaTime = video.value.currentTime; const file = await captureVideoFrame(video.value, captureCanvas, "palm-thunder-frame.jpg", { maxDimension: 640, quality: .72, mirror: true }); aborter = new AbortController(); const options: VisionOptions = { runtime: "auto", variant: "float", confidence: .65, iouThreshold: .45, maxDetections: 2, poseEnabled: false, faceEnabled: false, handEnabled: true, handConfidence: .6, handLandmarksEnabled: true, handLandmarkConfidence: .48, handInputMirrored: true }; const result = await estimatePoses(file, options, { signal: aborter.signal, cacheInput: false }); if (token !== generation) return; hands.value = tracker.update(result.hands, result.image_size.width, result.image_size.height, performance.now()); inferenceMs.value = result.parallel_timings.hand_ms } catch (e) { if (e instanceof DOMException && e.name === "AbortError") return; error.value = errorMessage(e, "Live hand tracking failed"); return } } }
function togglePause(): void { if (!engine) return; phase.value = phase.value === "paused" ? "playing" : "paused"; engine.setPhase(phase.value); lastAt = performance.now() }
function toggleSound(): void { soundEnabled.value = !soundEnabled.value; audio.enabled = soundEnabled.value }
function closeCamera(): void { stream.value?.getTracks().forEach((t) => t.stop()); stream.value = null; cameraReady.value = false; if (video.value) video.value.srcObject = null }
function exit(): void { generation++; cancelAnimationFrame(frameId); aborter?.abort(); observer?.disconnect(); closeCamera(); tracker.reset(); engine = null; renderer = null; snapshot.value = null; hands.value = []; pointerPosition.value = null; mouseStartRequested.value = false; phase.value = "lobby" }
function handleBack(): void { if (phase.value === "lobby") router.back(); else exit() }
onMounted(() => { document.body.classList.add("thunder-active"); void loadResource() })
onBeforeUnmount(() => { document.body.classList.remove("thunder-active"); exit(); void audio.close() })
</script>

<template>
  <div class="thunder">
    <button type="button" class="game-back" aria-label="Back" @click="handleBack">←</button>
    <main v-if="phase === 'lobby'" class="lobby">
      <section><p class="kicker">YOUR PALM IS THE FIGHTER</p><h1><span>Open your palm.</span><em>Break the barrage.</em></h1><p class="lead">A live single-player or co-op vertical shooter. Lock your hand before launch, steer with your palm, clench your fist to bomb the screen, and use 🤟 to revive your wingmate.</p>
        <div class="rules"><span><b>01</b>PALM OR MOUSE<br>MOVE YOUR FIGHTER</span><span><b>02</b>✊ FIST OR LEFT CLICK<br>SCREEN BOMB</span><span><b>03</b>HOLD 🤟 0.45s<br>LIVE REVIVE</span></div>
        <div class="player-count"><button :class="{ active: playerCount === 1 }" @click="playerCount = 1"><b>SOLO</b><small>LOCK ONE HAND</small></button><button :class="{ active: playerCount === 2 }" @click="playerCount = 2"><b>CO-OP</b><small>CALIBRATE TWO HANDS</small></button></div>
        <div class="difficulty"><button v-for="(item, key) in DIFFICULTIES" :key="key" :class="{ active: difficulty === key }" @click="difficulty = key">{{ item.label }}</button></div>
        <div class="model"><span :class="{ ready: modelInstanceId }"></span><b>HAND TRACKING · 21 LANDMARKS</b><small>{{ modelStatus }}</small><button :disabled="modelBusy || (!modelAvailable && !modelInstanceId)" @click="toggleModel">{{ modelInstanceId ? "UNLOAD" : "LOAD" }}</button></div>
        <button class="start" :disabled="modelBusy || !modelAvailable" @click="start">LAUNCH LIVE FIGHTER <b>START MISSION →</b></button><p v-if="error" class="error">{{ error }}</p>
      </section><aside aria-hidden="true" class="hangar-art">
        <div class="airshow">
          <div class="blast-ring blast-ring--outer"></div><div class="blast-ring blast-ring--inner"></div>
          <div class="shockwave"></div><div class="hero-fighter">🛩️</div>
          <div class="enemy-fighter enemy-fighter--one">✈️</div><div class="enemy-fighter enemy-fighter--two">✈️</div><div class="enemy-fighter enemy-fighter--three">🛸</div>
          <i class="laser laser--one"></i><i class="laser laser--two"></i><i class="laser laser--three"></i>
          <span class="spark spark--one">✦</span><span class="spark spark--two">✧</span><span class="spark spark--three">✦</span><span class="spark spark--four">✧</span>
        </div>
        <strong>CO-OP<br>READY</strong><small>HOVER TO DETONATE</small>
      </aside>
    </main>
    <main v-else ref="stage" class="arena" @pointermove="handlePointerMove" @pointerdown="handlePointerDown"><video ref="video" autoplay muted playsinline></video><canvas ref="canvas"></canvas><div class="vignette"></div>
      <div class="hud"><div v-for="p in joinedPlayers" :key="p.id" :class="`p${p.id}`"><b>PLAYER {{ p.id }} · {{ weaponLabel(p.weaponMode) }}</b><span>{{ p.score.toLocaleString() }}</span><small>LIVES {{ p.lives }}　BOMBS {{ p.bombs }}　LEVEL {{ p.weapon }}</small><em v-if="p.dead">WAITING FOR 🤟 REVIVE</em></div></div>
      <div v-if="snapshot?.bossHp != null" class="boss"><b>WARNING · SKY TYRANT INBOUND</b><span><i :style="{ width: `${100 * snapshot.bossHp / (snapshot.bossMaxHp || 1)}%` }"></i></span></div>
      <div class="tracking"><i></i>{{ statusText }}<small v-if="inferenceMs">{{ inferenceMs.toFixed(0) }} MS</small></div><div class="actions"><button :title="soundEnabled ? 'MUTE SOUND' : 'ENABLE SOUND'" @click="toggleSound">{{ soundEnabled ? "♪" : "×" }}</button><button v-if="phase === 'playing' || phase === 'paused'" :title="phase === 'paused' ? 'RESUME' : 'PAUSE'" @click="togglePause">{{ phase === "paused" ? "▶" : "Ⅱ" }}</button></div>
      <div v-if="phase === 'calibrating'" class="overlay"><div class="scanner">✋</div><p>CONTROL CALIBRATION · {{ hands.filter(h => h.active).length }}/{{ playerCount }}</p><h2>{{ playerCount === 2 ? "SHOW TWO OPEN PALMS" : "SHOW ONE OPEN PALM" }}</h2><span>{{ playerCount === 1 ? "Open your palm, or click anywhere to play with the mouse." : "Both players must show an open palm before launch." }}</span><button v-if="playerCount === 1" type="button" class="mouse-start" @click.stop="mouseStartRequested = true">PLAY WITH MOUSE</button></div>
      <div v-if="phase === 'countdown'" class="overlay clear"><p>MISSION START</p><h2 :key="countdown" class="count">{{ countdown }}</h2><span>PALM OR MOUSE TO MOVE · ✊ FIST OR LEFT CLICK TO BOMB · 🤟 TO REVIVE</span></div>
      <div v-if="phase === 'paused'" class="overlay"><p>MISSION PAUSED</p><h2>COMBAT PAUSED</h2><button @click="togglePause">RESUME</button></div>
      <div v-if="phase === 'won' || phase === 'lost'" class="overlay result"><p>{{ phase === "won" ? "MISSION COMPLETE" : "SQUADRON LOST" }}</p><h2>{{ phase === "won" ? "AIRSPACE SECURED" : "ALL FIGHTERS DOWN" }}</h2><div><span v-for="p in joinedPlayers" :key="p.id">PLAYER {{ p.id }}<b>{{ p.score.toLocaleString() }}</b></span></div><button @click="start">FLY AGAIN</button><button class="quiet" @click="exit">RETURN TO HANGAR</button></div>
    </main>
  </div>
</template>

<style scoped>
