.55rem var(--font-mono);background:#00101dcc;padding:.55rem .8rem;border-radius:10px}.tracking i{display:inline-block;width:.45rem;height:.45rem;border-radius:50%;background:#6cff91;box-shadow:0 0 10px #6cff91;margin-right:.5rem}.tracking small{color:#66859b;margin-left:.6rem}.actions{right:1rem;bottom:1rem;display:flex;gap:.4rem}.actions button,.overlay button{background:#ffffff16;border:1px solid #ffffff33;border-radius:9px;color:#fff;padding:.65rem 1rem}.boss{top:1.1rem;left:50%;transform:translateX(-50%);width:min(38rem,48vw);text-align:center}.boss b{font:.6rem var(--font-mono);color:#ff826f}.boss span{display:block;height:.45rem;background:#2b0710;border:1px solid #ff4c55;margin-top:.35rem}.boss i{display:block;height:100%;background:linear-gradient(90deg,#ff3255,#ffb333)}.overlay{position:absolute;z-index:10;inset:0;background:#010916de;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.overlay.clear{background:#00102055}.overlay p{color:#45e7ff;font:700 .65rem var(--font-mono);letter-spacing:.2em}.overlay h2{font-size:clamp(2.6rem,7vw,6.5rem);margin:.4rem}.overlay>span{color:#91a8bb}.scanner{font-size:7rem;filter:drop-shadow(0 0 25px #45e7ff);animation:pulse 1.2s infinite}.count{font:900 min(28vw,16rem) var(--font-mono);animation:slam .7s ease-out}.result div{display:flex;gap:2rem;margin:1rem}.result div span{font:.7rem var(--font-mono)}.result div b{font-size:1.6rem;display:block}.result button{min-width:12rem;margin-top:.5rem;background:#45e7ff;color:#02101a;font-weight:900}.result button.quiet{background:transparent;color:#fff}@keyframes pulse{50%{transform:scale(1.08)}}@keyframes slam{from{opacity:0;transform:scale(1.8)}}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:760px){.lobby{grid-template-columns:1fr}.lobby aside{display:none}.lobby section{padding:2rem 1rem}.rules{grid-template-columns:1fr}.rules span{border-right:0;border-bottom:1px solid #ffffff14}.hud{gap:.35rem}.hud>div{min-width:7.5r